$(function () {
  $("#preloader").remove();
  $("#main-wrapper").addClass("show");

  var $hamburger = $(".hamburger");
  var isMini = $("body").attr("data-sidebar-style") === "mini";
  $hamburger.toggleClass("is-active", isMini);
  $hamburger.attr("aria-expanded", String(isMini));
});

/* Accessibility helper: announce messages to screen readers via live regions */
window.a11yAnnounce = function (message, priority) {
  var el = document.getElementById(
    priority === "assertive" ? "a11y-alert" : "a11y-status"
  );
  if (el) {
    el.textContent = "";
    setTimeout(function () {
      el.textContent = message;
    }, 100);
  }
};

(function ($) {
  "use strict";

  // #menu is a flat list with no submenus, so metisMenu had nothing to do and was removed.


  $(".nav-control").on("click", function () {
    $("#main-wrapper").toggleClass("menu-toggle");

    var $hamburger = $(".hamburger");
    $hamburger.toggleClass("is-active");
    $hamburger.attr("aria-expanded", String($hamburger.hasClass("is-active")));
  });

  $(function () {
    for (
      var nk = window.location,
        o = $("ul#menu a")
          .filter(function () {
            return this.href == nk;
          })
          .addClass("active")
          .parent()
          .addClass("active");
      ;

    ) {
      if (!o.is("li")) break;
      o = o.parent().addClass("in").parent().addClass("active");
    }
  });

  var resizeTimeout;

  function adjustContentMinHeight() {
    var $content = $(".content-body").first();
    if (!$content.length) {
      return;
    }

    var viewportHeight = Math.max(
      window.innerHeight || 0,
      document.documentElement ? document.documentElement.clientHeight || 0 : 0
    );

    if (!viewportHeight) {
      return;
    }

    var $footer = $(".footer").first();
    if (!$footer.length) {
      return;
    }

    var footerHeight = $footer.outerHeight(true) || 0;
    var contentOffsetTop = ($content.offset() && $content.offset().top) || 0;

    // Calculate the minimum height needed to push footer to bottom
    var minHeight = viewportHeight - contentOffsetTop - footerHeight;
    
    if (minHeight < 0) {
      minHeight = 0;
    }

    $content.css("min-height", minHeight + "px");
    
    // Multi-pass adjustment to handle layout reflow
    if (window.requestAnimationFrame) {
      var maxPasses = 3;
      var passCount = 0;
      
      function checkAndAdjust() {
        passCount++;
        
        window.requestAnimationFrame(function() {
          // Get the actual footer position using getBoundingClientRect for accuracy
          var footerRect = $footer[0].getBoundingClientRect();
          var footerBottom = footerRect.bottom;
          
          // Calculate how much we're off from the viewport bottom
          var diff = viewportHeight - footerBottom;
          
          // If footer is not at the bottom (diff > 1px) and we haven't exceeded max passes
          if (Math.abs(diff) > 1 && passCount < maxPasses) {
            var currentMinHeight = parseFloat($content.css("min-height")) || 0;
            var newMinHeight = currentMinHeight + diff;
            
            if (newMinHeight < 0) {
              newMinHeight = 0;
            }
            
            $content.css("min-height", newMinHeight + "px");
            
            // Check again after this adjustment
            checkAndAdjust();
          }
        });
      }
      
      checkAndAdjust();
    }
  }

  $(function () {
    adjustContentMinHeight();
  });

  $(window).on("load.contentBodyAdjust", adjustContentMinHeight);

  $(window).on("resize.contentBodyAdjust", function () {
    clearTimeout(resizeTimeout);
    resizeTimeout = setTimeout(adjustContentMinHeight, 100);
  });

  // bootstrap-select was removed together with its stylesheet; nothing uses .selectpicker.

  // Bootstrap 5 removed the jQuery plugin API, so components are constructed directly.
  document.querySelectorAll('[data-bs-toggle="popover"]').forEach(function (el) {
    new bootstrap.Popover(el);
  });
  document.querySelectorAll('[data-bs-toggle="tooltip"]').forEach(function (el) {
    new bootstrap.Tooltip(el);
  });

  const headerHight = $(".header").innerHeight();

  $(window).scroll(function () {
    if (
      $("body").attr("data-layout") === "horizontal" &&
      $("body").attr("data-header-position") === "static" &&
      $("body").attr("data-sidebar-position") === "fixed"
    )
      $(this.window).scrollTop() >= headerHight
        ? $(".metismenu").addClass("fixed")
        : $(".metismenu").removeClass("fixed");
  });

  $(".sidebar-right-trigger").on("click", function () {
    $(".sidebar-right").toggleClass("show");
  });

  $(function () {
    // Sweep legacy persistent localStorage keys so no remnants stay in the browser.
    try {
      if (window.localStorage) {
        var exactLegacyKeys = [
          "ankicollab_cookie_dismissed",
          "ankicollab_mathjax_enabled",
          "diffViewPreference",
        ];
        for (var k = 0; k < exactLegacyKeys.length; k++) {
          localStorage.removeItem(exactLegacyKeys[k]);
        }
        for (var i = localStorage.length - 1; i >= 0; i--) {
          var legacyKey = localStorage.key(i);
          if (legacyKey && legacyKey.indexOf("commit_select::") === 0) {
            localStorage.removeItem(legacyKey);
          }
        }
      }
    } catch (error) {
      /* Ignore storage access failures */
    }

    var cookieDismissKey = "ankicollab_cookie_dismissed";
    var banner = document.getElementById("global-cookie-banner");
    if (!banner) {
      return;
    }

    var mainWrapper = document.getElementById("main-wrapper");
    var isDismissed = false;
    try {
      isDismissed = sessionStorage.getItem(cookieDismissKey) === "true";
    } catch (error) {
      isDismissed = false;
    }

    if (!isDismissed) {
      banner.classList.remove("d-none");
      banner.style.display = "block";
      if (mainWrapper) {
        mainWrapper.style.paddingBottom = banner.offsetHeight + "px";
      }
    }

    var closeButton = document.getElementById("global-cookie-banner-close");
    if (closeButton) {
      closeButton.addEventListener("click", function () {
        if (mainWrapper) {
          mainWrapper.style.paddingBottom = "";
        }
        try {
          sessionStorage.setItem(cookieDismissKey, "true");
        } catch (error) {
          /* Ignore storage failures and allow dismiss to continue */
        }
      });
    }
  });
})(jQuery);
